function tarjetaPalletDespacho14(p,v,accion='',m='prepacking'){const inicio=m==='prepacking'?p.despachoHoraInicio:p.ingreso,fin=m==='prepacking'?p.despachoHoraFin:v?.cierre;return `<article class="uva-pallet pallet-card"><p class="viaje-sap14">Viaje SAP: <b>${safe(v?.viajeSAP||'')}</b></p><div class="fila-parcela"><b>PALLET: ${safe(p.codigoQR)}</b>${accion}</div><p>Tipo de embalaje: ${safe(p.embalaje)}</p><p class="horas-despacho14">Inicio: <b>${safe(fechaVisibleCAP(inicio))}</b> · Fin: <b>${safe(fechaVisibleCAP(fin))}</b></p>${m==='despacho'&&p.origenTraza?`<p class="origen-traza">${p.origenTraza.camaraGasificado?'Origen gasificado: '+safe(p.origenTraza.camaraGasificado):''}${p.origenTraza.tunelEnfriado?' · Origen enfriado: '+safe(p.origenTraza.tunelEnfriado):''}</p>`:''}<div class="fila-parcela fila-temperatura"><span>Temp. prom.: <b>${Number(p.tempPromedio).toFixed(2)} °C</b></span><b class="cantidad-jabas">${p.cant} ${iconoConteo('jaba')}</b></div><div class="detalle-producto"><div class="fila-parcela"><b>Parcela: ${safe(p.parcela)}</b><span>Tipo: ${safe(p.tipo)}</span></div>${(p.lineas||[]).map(i=>`<p>${i.cant} ${textoLinea(i,p.tipo)}<small>${metaLinea(i)}</small></p>`).join('')}</div></article>`;}
const grupoAntes14=grupoTransferenciaCAP;
grupoTransferenciaCAP=function(m){if(m!=='prepacking')return grupoAntes14(m);const d=registroUva(m),ps=d.grupo.map(id=>palletsEtapa(m).find(p=>p.id===id)).filter(Boolean);return `<section class="cap-grupo"><div class="uva-persona"><div class="fila-parcela"><b>Agrupación:</b>${conteosPallets(ps)}</div><div class="uva-grupo-botones"><button onclick="camaraUva('prepacking','agregar')"><i class="fa-solid fa-camera"></i> Añadir</button><button onclick="abrirGuiaPreCAP()">Guía y precinto</button><button onclick="cerrarTransferenciaCAP('prepacking')" ${ps.length?'':'disabled'}><i class="fa-solid fa-lock"></i> Cerrar</button></div>${d.guia&&d.precinto?`<p>Guía: ${safe(d.guia)} · Precinto: ${safe(d.precinto)}</p>`:''}</div>${ps.slice().reverse().map(p=>tarjetaPalletDespacho14(p,null,`<button class="cap-eliminar" onclick="quitarTransferenciaCAP('prepacking','${p.id}')" aria-label="Eliminar pallet"><i class="fa-solid fa-trash"></i></button>`)).join('')}</section>`;};
