const tarjetasViajeAntes14=tarjetaViajeDesplegable13;
tarjetaViajeDesplegable13=function(v,m){if(!['prepacking','despacho'].includes(m))return tarjetasViajeAntes14(v,m);const ps=v.palletsDetalle||palletsEtapa(m).filter(p=>v.palletIds.includes(p.id)),confirmado=!!v.confirmacion;return `<article class="uva-viaje viaje-desplegable"><details><summary><div class="viaje-header13"><b>AGRUPACIÓN · Viaje: ${safe(v.viajeSAP||v.id)}</b><div class="viaje-conteos13">${conteosPallets(ps)}<span class="viaje-estado14 ${confirmado?'confirmado':'proceso'}">${confirmado?'Confirmado':'En proceso'}</span><button class="uva-qr" onclick="abrirQRResumen13(event,'${m}','${v.id}')" aria-label="Abrir QR y detalle del viaje"><i class="fa-solid fa-qrcode"></i></button></div><span class="viaje-flecha13" aria-hidden="true">⌄</span></div></summary><div class="viaje-cuerpo13"><p>Código de despacho T2: ${safe(v.id)}</p>${v.guia?`<p>Guía de remisión: ${safe(v.guia)}</p>`:''}${v.precinto?`<p>Precinto: ${safe(v.precinto)}</p>`:''}<p>Conductor: <b>${safe(v.conductor||'—')}</b></p><p>Placa: ${safe(v.placa||'—')}</p><p>Recepcionó: <b>${safe(v.usuarioRecepcion||'—')}</b> · Hora: ${safe(fechaVisibleCAP(v.recepcion||v.confirmacion))}</p>${ps.slice().reverse().map(p=>tarjetaPalletDespacho14(p,v,'',m)).join('')}</div></details><button class="obtener-viaje" onclick="obtenerViajeResumen13('${m}','${v.id}',this)" ${v.viajeSAP?'disabled':''}>${v.viajeSAP?'Viaje obtenido':'↻ Obtener viaje SAP'}</button></article>`;};
const abrirComprobanteAntes14=abrirComprobanteV11;
abrirComprobanteV11=function(id){const dato=viajeEntregaV11(id);if(!dato||!['prepacking','despacho'].includes(dato.m))return abrirComprobanteAntes14(id);const {v,m}=dato,gestion=contextoCierreV11===m,ps=v.palletsDetalle||palletsEtapa(m).filter(p=>v.palletIds.includes(p.id));let modal=document.getElementById('cap-detalle');if(!modal){modal=document.createElement('div');modal.id='cap-detalle';modal.className='overlay-local';document.getElementById('app-shell').appendChild(modal);}modal.innerHTML=`<div class="dialogo-tarjeta cap-detalle"><header><h2>QR de entrega a T2</h2></header><div class="cap-detalle-cuerpo"><div id="cap-qr" class="qr-centro"></div>${conteosPallets(ps)}<p>${m==='prepacking'?'Croquista':'Envió'}: ${safe(v.usuario)}${m==='prepacking'?'':` · ${safe(fechaVisibleCAP(v.cierre))}`}</p>${v.guia?`<p>Guía de remisión: ${safe(v.guia)}</p>`:''}${v.precinto?`<p>Precinto: ${safe(v.precinto)}</p>`:''}${ps.map(p=>{const card=tarjetaPalletDespacho14(p,v,'',m);return card.replace(/<p class="viaje-sap14">[\s\S]*?<\/p>/g,'');}).join('')}${!v.recepcion&&!v.confirmacion?`<div class="uva-grupo-botones"><button onclick="continuarT2DesdeQR14('${id}',true)">Simular entrega T2</button><button onclick="continuarT2DesdeQR14('${id}',false)">Escanear confirmación T2</button></div>`:''}</div><footer><button onclick="${gestion?`aceptarEntregaV11('${m}')`:"document.getElementById('cap-detalle').classList.add('hidden')"}">${gestion?'Aceptar':'Cerrar'}</button></footer></div>`;modal.classList.remove('hidden');generarQR('cap-qr',m==='prepacking'?payloadTransferCAP(v):{tipo:'DESPACHO_UVA',viaje:v.id,viajeSAP:v.viajeSAP||null,guia:v.guia,precinto:v.precinto,cant:v.cant,pallets:ps.map(p=>({qr:p.codigoQR,cant:p.cant}))});};
verTransferenciaCAP=abrirComprobanteV11;verViajeUva=abrirComprobanteV11;
async function continuarT2DesdeQR14(id,simular){const dato=viajeEntregaV11(id);if(!dato)return;document.getElementById('cap-detalle')?.classList.add('hidden');if(simular){await recepcionarEntregaT2CAP(id,true);if(dato.v.recepcion)aceptarEntregaV11(dato.m);}else escanearEntregaV11(dato.m);}
