recepcionarEntregaT2CAP=async function(raw,simulado=false){const v=buscarEntregaT2CAP(raw),antes=v?.recepcion;await recibirT2Antes14(raw,simulado);if(v&&!antes&&v.recepcion&&simulado){v.conductor ||= 'CONDUCTOR DE PRUEBA';v.placa ||= 'PRUEBA';guardarLocal();}};

/* Conteos de Exportable/Industrial, siempre con íconos y sin texto de unidades. */
function industrialPallet15(p){if(industrial(p))return true;return !!p.lineas?.length&&p.lineas.every(industrial);}
function filaConteo15(nombre,jabas,pallets){return `<div class="categoria-conteo15"><b>${nombre}</b><div>${pallets===undefined?'':`<span aria-label="${pallets} pallets">${pallets} ${iconoConteo('pallet')}</span>`}<span aria-label="${jabas} jabas">${jabas} ${iconoConteo('jaba')}</span></div></div>`;}
function conteosCategorias15(ps){const ex=ps.filter(p=>!industrialPallet15(p)),ind=ps.filter(industrialPallet15);return `<div class="conteos-categorias15">${filaConteo15('Exportable',suma(ex),ex.length)}${filaConteo15('Industrial',suma(ind),ind.length)}</div>`;}
totalesHTML=function(lineas,pallets){return pallets?conteosCategorias15(pallets):`<div class="conteos-categorias15">${filaConteo15('Exportable',suma(lineas.filter(x=>!industrial(x))))}${filaConteo15('Industrial',suma(lineas.filter(industrial)))}</div>`;};
function seleccionadoDespacho15(p){const d=registroUva('prepacking');return d.grupo.includes(p.id)||d.viajes.some(v=>v.palletIds.includes(p.id));}
const tarjetaAntes15=tarjetaPallet;
tarjetaPallet=function(p,e=false){const card=tarjetaAntes15(p,e);if(p.estado==='CERRADO'&&seleccionadoDespacho15(p)){card.classList.add('pallet-seleccionado-despacho15');card.setAttribute('aria-label','Pallet '+p.codigoQR+' seleccionado en Despacho');}return card;};
renderPalletsCerradosTransferencia=function(){const c=document.getElementById('lista-pallets-cerrados-historial');if(!c)return;const ps=AppState.palletsAcopio.filter(p=>p.estado==='CERRADO'&&pasaFiltro(p,p.lineas||[]));c.innerHTML=conteosCategorias15(ps);ps.slice().reverse().forEach(p=>c.appendChild(tarjetaPallet(p)));if(!ps.length)c.insertAdjacentHTML('beforeend','<p class="estado-vacio">No hay pallets cerrados.</p>');};
renderPalletsEnProceso=function(){const c=document.getElementById('lista-pallets-proceso');if(!c)return;const ps=AppState.palletsAcopio.filter(p=>p.estado!=='CERRADO'&&pasaFiltro(p,p.lineas||[{formato:p.formato}]));c.innerHTML=conteosCategorias15(ps);ps.slice().reverse().forEach(p=>c.appendChild(tarjetaPallet(p,true)));if(!ps.length)c.insertAdjacentHTML('beforeend','<p class="estado-vacio">No hay pallets en proceso.</p>');};
