async function enviarInformacion28(m){if(!['cosecha','transporte','prepacking','gasificado','enfriado','despacho'].includes(m))return;guardarLocal();if(!await confirmarApp('¿Preparar la información de este módulo? Se descargará un archivo para compartir.'))return;const contenido={modulo:m,generado:fechaUva(),datos:datosEnvioModulo28(m)},url=URL.createObjectURL(new Blob([JSON.stringify(contenido,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='CAP_UVA_'+m+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);avisoApp('Archivo preparado. El envío a un servidor todavía no está configurado.');}

