function controlesPaletizado29(p){const idx=AppState.palletsAcopio.indexOf(p),cerrado=p.estado==='CERRADO';return `<div class="embalaje-pal29"><span>Tipo Embalaje: ${safe(p.embalaje)} ${cerrado?'':`<button onclick="editarEmbalaje(${idx})" aria-label="Editar embalaje"><i class="fa-solid fa-pencil"></i></button>`}</span><div class="acciones-pal29"><button ${cerrado?'disabled':`onclick="escanearPallet(${idx})"`} aria-label="${cerrado?'Cámara bloqueada':'Escanear QR del pallet'}"><i class="fa-solid fa-camera"></i></button><button ${cerrado?'disabled':`onclick="eliminarPallet(${idx})"`} aria-label="${cerrado?'Eliminación bloqueada':'Eliminar pallet'}"><i class="fa-solid fa-trash"></i></button><strong class="${cerrado?'estado-cerrado39':'estado-proceso39'}">${cerrado?'CERRADO':'EN PROCESO'}</strong></div></div>`;}
