function conductorPrueba29(v){const nombres=['Juan Vásquez','Luis Bautista','Omar Mariños'],placas=['KW-120','KW-130','KW-140'];let i=Array.from(String(v.id||'')).reduce((n,c)=>n+c.charCodeAt(0),0)%nombres.length;if(nombres[i].toUpperCase()===usuarioUva().toUpperCase())i=(i+1)%nombres.length;return {nombre:nombres[i],placa:placas[i]};}
