// Disponibilidad única por etapa; el cierre de transferencia libera el pallet.
function fuenteSecuencia30(code,m){const siguiente={prepacking:['gasificado'],gasificado:['enfriado','despacho'],enfriado:['despacho'],despacho:[]};if(!['gasificado','enfriado','despacho'].includes(m)||entregadoT231(code))return null;const pre=AppState.palletsAcopio.find(p=>p.codigoQR===code&&p.estado==='CERRADO');if(!pre)return null;let origen=pre,modulo='prepacking';for(const etapa of ['gasificado','enfriado','despacho']){const encontrado=registroUva(etapa).pallets.find(p=>p.codigoQR===code);if(encontrado){origen=encontrado;modulo=etapa;}}if(!siguiente[modulo].includes(m))return null;const viaje=registroUva(modulo).viajes.find(v=>v.cierre&&v.palletIds.includes(origen.id)&&!(v.recibidos||[]).includes(code));if(!viaje||(modulo!=='prepacking'&&!origen.salida))return null;return {pre,origen,modulo,viaje};}

fuentePalletV11=fuenteSecuencia30;
const recibirSecuenciaAntes30=recibirPalletV11;
recibirPalletV11=async function(m,code,opciones={}){const fuente=fuenteSecuencia30(code,m);if(!fuente)return avisoApp('Pallet no disponible: cierre la transferencia del módulo anterior. No se permiten duplicados ni retrocesos.');return recibirSecuenciaAntes30(m,code,{...opciones,viaje:fuente.viaje});};
const cabeceraAntes30=cabeceraUva;
cabeceraUva=function(m){let html=cabeceraAntes30(m);if(AppState.currentView===m+'-gestion')html=html.replace('Usuario:',({gasificado:'Gasificador:',enfriado:'Enfriador:',despacho:'Encargado de despacho:'})[m]||'Usuario:');return html;};
let ocultarOrigenRecepcion30=false;
