tarjetaUva=function(p,m,a=''){const html=tarjetaAntes30(p,m,a);return m==='despacho'&&ocultarOrigenRecepcion30?html.replace(/<div class="traza-pallet">[\s\S]*?<\/div>/g,'').replace(/<p class="origen-traza">[\s\S]*?<\/p>/g,''):html;};
