// Un QR representa una entrega específica: los viajes anteriores no se reutilizan.
function codigosViaje31(v,m){return v.codigos||palletsEtapa(m).filter(p=>(v.palletIds||[]).includes(p.id)).map(p=>p.codigoQR);}
function entregadoT231(code){return ['prepacking','despacho'].some(m=>registroUva(m).viajes.some(v=>(v.entregaT2||((v.destino==='t2'||m==='despacho')&&v.confirmacion))&&codigosViaje31(v,m).includes(code)));}
function pendientesViaje31(v,m){const origen=v.origen||viajeEntregaV11(v.id)?.m;return codigosViaje31(v,origen).filter(code=>!(v.recibidos||[]).includes(code)&&fuenteSecuencia30(code,m)?.viaje.id===v.id);}
function disponibleT231(v,m){if(!v.cierre||v.recepcion||v.confirmacion)return false;return codigosViaje31(v,m).length>0&&codigosViaje31(v,m).every(code=>{if(entregadoT231(code))return false;if(m==='prepacking')return !['gasificado','enfriado','despacho'].some(etapa=>registroUva(etapa).pallets.some(p=>p.codigoQR===code))&&!(v.recibidos||[]).includes(code);return registroUva('despacho').pallets.some(p=>p.codigoQR===code&&v.palletIds.includes(p.id));});}
const lecturaAntes31=leerPalletUva;
leerPalletUva=async function(m,op,raw){if(!['gasificado','enfriado','despacho'].includes(m)||!['ingreso','recepcion'].includes(op))return lecturaAntes31(m,op,raw);let data;try{data=JSON.parse(raw);}catch{}const dato=viajeEntregaV11(data?.transferencia||data?.viaje||raw);if(!dato)return lecturaAntes31(m,op,raw);const pendientes=pendientesViaje31(dato.v,m);if(!pendientes.length)return avisoApp('Este viaje ya fue recibido o pertenece a una etapa anterior. Lea el QR de la nueva transferencia.');if(lecturaRecepcionV11)return;lecturaRecepcionV11=true;try{for(const code of pendientes){if(!await recibirPalletV11(m,code,{viaje:dato.v}))break;}guardarLocal();}finally{lecturaRecepcionV11=false;}};
const recibirAntes31=recibirPalletV11;
const palletsRecepcionOcupados31=new Set();
recibirPalletV11=async function(m,code,opts={}){const fuente=fuenteSecuencia30(code,m);if(!fuente||opts.viaje&&opts.viaje.id!==fuente.viaje.id)return avisoApp('Pallet o viaje no disponible para este módulo.');if(palletsRecepcionOcupados31.has(code))return;palletsRecepcionOcupados31.add(code);try{return await recibirAntes31(m,code,opts);}finally{palletsRecepcionOcupados31.delete(code);}};
const camaraAntes31=camaraUva;
camaraUva=function(m,op){if(!['gasificado','enfriado','despacho','t2'].includes(m)||!['ingreso','recepcion'].includes(op))return camaraAntes31(m,op);if(m!=='t2'&&!registroUva(m).config)return avisoApp('Guarde primero el registro.');if(['gasificado','enfriado'].includes(m)&&!ubicacionesUva[m])return avisoApp('Seleccione '+(m==='gasificado'?'una cámara.':'un túnel.'));const modal=document.getElementById('modal-uva-prueba'),ps=m==='t2'?[]:AppState.palletsAcopio.filter(p=>fuenteSecuencia30(p.codigoQR,m)),vs=m==='t2'?['prepacking','despacho'].flatMap(etapa=>registroUva(etapa).viajes.filter(v=>disponibleT231(v,etapa))):transferenciasCAP().filter(v=>pendientesViaje31(v,m).length);modal.dataset.modulo=m;modal.dataset.operacion=op;document.getElementById('uva-lista-prueba').innerHTML=vs.slice().reverse().map(v=>`<option value="${safe(v.id)}">QR ${safe(v.id)} · ${m==='t2'?codigosViaje31(v,viajeEntregaV11(v.id).m).length:pendientesViaje31(v,m).length} pallets</option>`).join('')+ps.slice().reverse().map(p=>`<option value="${p.codigoQR}">${p.codigoQR} · ${p.cant} jabas</option>`).join('');document.getElementById('uva-simular').disabled=!vs.length&&!ps.length;document.getElementById('uva-prueba-nota').textContent=vs.length||ps.length?'Solo entregas y pallets pendientes de esta etapa.':'No hay entregas disponibles.';modal.classList.remove('hidden');};
const receptorAntes31=recepcionarEntregaT2CAP;
recepcionarEntregaT2CAP=async function(raw,simulado=false){const v=buscarEntregaT2CAP(raw),dato=v?viajeEntregaV11(v.id):null;if(!dato||!disponibleT231(v,dato.m))return avisoApp('Esta entrega no está disponible para Transporte externo.');await receptorAntes31(raw,simulado);if(v.confirmacion){v.entregaT2=true;v.moduloRecepcion='t2';v.recibidos=codigosViaje31(v,dato.m).slice();guardarLocal();}};

// Salida manual individual o masiva, sin sustituir la lectura de cámara.
const seleccionSalida33={gasificado:new Set(),enfriado:new Set()};
const modoSalida33={gasificado:false,enfriado:false};
let tarjetasSeleccion33=null;
const tarjetaAntes33=tarjetaUva;
tarjetaUva=function(p,m,a=''){const html=tarjetaAntes33(p,m,a);if(tarjetasSeleccion33!==m||!modoSalida33[m])return html;return html.replace('<div class="fila-parcela">',`<div class="fila-parcela"><label class="seleccion-pallet33"><input type="checkbox" aria-label="Seleccionar pallet ${safe(p.codigoQR)}" ${seleccionSalida33[m].has(p.id)?'checked':''} onchange="marcarSalida33('${m}','${safe(p.id)}',this.checked)"></label>`);};
function pendientesSalida33(m){return registroUva(m).pallets.filter(p=>!p.salida);}
function marcarSalida33(m,id,marcado){if(marcado)seleccionSalida33[m].add(id);else seleccionSalida33[m].delete(id);renderUva(m,'gestion');}
function activarSalida33(m){modoSalida33[m]=!modoSalida33[m];seleccionSalida33[m].clear();renderUva(m,'gestion');}
function todosSalida33(m){const ps=pendientesSalida33(m).filter(p=>filtrosSemaforoCAP[m].ingreso==='todos'||colorSemaforoCAP(p)===filtrosSemaforoCAP[m].ingreso);const completos=ps.every(p=>seleccionSalida33[m].has(p.id));ps.forEach(p=>completos?seleccionSalida33[m].delete(p.id):seleccionSalida33[m].add(p.id));renderUva(m,'gestion');}
const ocupadaSalida33=new Set();
async function guardarSalida33(m){if(!['gasificado','enfriado'].includes(m)||ocupadaSalida33.has(m))return;ocupadaSalida33.add(m);try{let ps=pendientesSalida33(m).filter(p=>seleccionSalida33[m].has(p.id));if(!ps.length)return avisoApp('Seleccione al menos un pallet.');if(!await confirmarApp('¿Dar salida a '+ps.length+' pallets?'))return;const destino=m==='gasificado'?await elegirDestinoGasificado():'despacho';if(!destino)return;ps=pendientesSalida33(m).filter(p=>seleccionSalida33[m].has(p.id));const ahora=fechaUva();for(const p of ps){Object.assign(p,{salida:ahora,destinoSalida:destino,usuarioSalida:usuarioUva()});if(m==='gasificado'){const origen=AppState.palletsAcopio.find(x=>x.codigoQR===p.codigoQR);if(origen){origen.destino=destino==='enfriado'?'PLANTA ENFRIADO':'DESPACHO';ajustarCantidadPallet(origen,p.cant);}}}guardarLocal();modoSalida33[m]=false;seleccionSalida33[m].clear();tabUva(m,'salida');}finally{ocupadaSalida33.delete(m);}}
const renderAntes33=renderUva;
renderUva=function(m,p){tarjetasSeleccion33=p==='gestion'&&uvaTabs[m]==='ingreso'&&seleccionSalida33[m]?m:null;try{renderAntes33(m,p);}finally{tarjetasSeleccion33=null;}if(p!=='gestion'||uvaTabs[m]!=='ingreso'||!seleccionSalida33[m])return;const ps=pendientesSalida33(m);for(const id of seleccionSalida33[m])if(!ps.some(x=>x.id===id))seleccionSalida33[m].delete(id);const n=seleccionSalida33[m].size;document.querySelector('#uva-'+m+'-gestion .uva-contadores')?.insertAdjacentHTML('afterend',`<div class="salida-masiva33"><button onclick="activarSalida33('${m}')">${modoSalida33[m]?'Cancelar':'Seleccionar'}</button>${modoSalida33[m]?`<button onclick="todosSalida33('${m}')">Seleccionar todo</button><button onclick="guardarSalida33('${m}')" ${n?'':'disabled'}>Dar salida (${n})</button>`:''}</div>`);};
// Acceso explícito a la simulación T2 del último viaje pendiente en Prepacking.
const transferAntes33=renderTransferGestionCAP;
renderTransferGestionCAP=function(m){transferAntes33(m);if(m!=='prepacking')return;const v=registroUva(m).viajes.slice().reverse().find(v=>disponibleT231(v,m));if(v)document.getElementById('subview-acopio-viajes')?.insertAdjacentHTML('beforeend',`<div class="salida-masiva33"><button onclick="continuarT2DesdeQR14('${safe(v.id)}',true)">Simular entrega al T2</button><button onclick="abrirComprobanteV11('${safe(v.id)}')">Ver QR de entrega</button></div>`);};
